const $=(s)=>document.querySelector(s), $$=(s)=>Array.from(document.querySelectorAll(s));
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=x=>new Intl.NumberFormat('pt-BR',{maximumFractionDigits:2}).format(x||0);
const brl=x=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(x||0);
const safeUrl=x=>{try{const u=new URL(x,location.origin);return ['http:','https:'].includes(u.protocol)?u.href:'#home';}catch{return '#home';}};
const iconPaths={home:'M3 11 12 3l9 8v10h-6v-6H9v6H3Z',robot:'M6 6h12v13H6z M9 10h.1 M15 10h.1 M9 15h6 M12 6V3 M3 10v6 M21 10v6',story:'M4 19h4l4-14h4l4 14 M3 8h5 M16 8h5 M8 15h8',arena:'M5 3 20 18l-2 2L3 5Z M19 3 13 9 M3 19l5-5 M16 16l4 4',shop:'M5 7h14l2 14H3Z M8 7V5a4 4 0 0 1 8 0v2',wallet:'M3 5h17v15H3Z M3 8h17 M16 11h5v5h-5Z',users:'M16 21v-3a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v3 M9 3a4 4 0 1 0 0 8 4 4 0 1 0 0-8 M17 4a4 4 0 0 1 0 7 M20 15a4 4 0 0 1 3 4',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 1 0 0-8 M9 3h6l1 4 4 1v7l-4 1-1 5H9l-1-5-5-1V8l5-1Z',arrow:'M4 12h16 M14 6l6 6-6 6',plus:'M12 5v14 M5 12h14',bolt:'m13 2-9 12h7l-1 8 10-12h-7Z',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z',check:'m4 12 5 5L20 6',close:'m6 6 12 12 M18 6 6 18',chevron:'m9 5 7 7-7 7',gift:'M3 9h18v5H3Z M5 14v7h14v-7 M12 9v12 M12 9S4 9 5 4c1-3 7 0 7 5 0-5 6-8 7-5 1 5-7 5-7 5',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 1 0 0-18 M12 7v5l4 2',logout:'M9 3H3v18h6 M8 12h13 M16 7l5 5-5 5',copy:'M9 8h12v13H9Z M15 8V3H3v13h6',info:'M12 3a9 9 0 1 0 0 18 9 9 0 1 0 0-18 M12 11v6 M12 7h.1',core:'m12 2 9 5v10l-9 5-9-5V7Z M12 8l4 4-4 4-4-4Z',arm:'M3 17h5l3-5-3-4 3-5h5l4 4-4 4h-3l-2 6-4 4H3Z',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3Z',bell:'M5 16h14l-2-3V9a5 5 0 0 0-10 0v4Z M9 20h6',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12 M12 9a3 3 0 1 0 0 6 3 3 0 1 0 0-6'};
const I=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.spark}"/></svg>`;
const coin=(type)=>`<span class="coin ${type.toLowerCase()}" aria-hidden="true"><img src="${assetUrl(type==='LC'?'lifecoin.png':'robotcoin.png')}" alt="" decoding="async"></span>`;
const btn=(label,action,extra='',cls='primary')=>`<button class="btn ${cls}" data-a="${action}" ${extra}>${label}</button>`;
const navs=[['home','Hangar','home'],['robots','Meus robôs','robot'],['story','Modo história','story'],['arena','Arena','arena'],['shop','Oficina','shop'],['wallet','Carteira','wallet'],['affiliates','Minha rede','users'],['guilds','Guildas','shield'],['market','Mercado de robôs','shop'],['chat','Chat global','users'],['events','Eventos','gift']];
let state;
try{state=API.isDemo?JSON.parse(localStorage.getItem(C.STORAGE_KEY)||'null'):null;}catch{}
if(API.isDemo)state=C.hydrateState(state);else if(!state||state.version!==1)state=C.initialState();
if(!API.isDemo)state={...C.initialState(),serverAuthoritative:true,profile:{name:'Piloto',level:1,tutorial:false},balances:{LC:0,RC:0},depositedCents:0,withdrawnCents:0,robots:[],inventory:[],transactions:[],affiliates:[],battles:[],commissionTotal:0,story:0,selectedRobot:null};
if(API.isDemo){ensureDemoAdmin(state);ensureSocial(state);}
let page=location.hash.slice(1).split('?')[0]||'home',shopTab='robots',affiliateTab=0,adminTab='economy',authMode='login',tutorialStep=0,modalFocus=null,combat=null,matchmaking=null,installPrompt=null,remoteLoaded=API.isDemo;
let signupReferral='';try{signupReferral=referralFromUrl(location.href);}catch{}
if(page==='signup'||signupReferral){page='login';authMode='signup';}
const audio=createGameAudio({getConfig:()=>state.settings.audio});
const copy=(key,fallback)=>esc(state.settings.copy?.[key]??fallback);
const ui=html=>applyTextOverrides(html,state.settings.textOverrides,esc);
iconPaths.volume='M3 9h4l5-4v14l-5-4H3Z M16 8a6 6 0 0 1 0 8 M19 5a10 10 0 0 1 0 14';
const save=()=>{if(API.isDemo)try{localStorage.setItem(C.STORAGE_KEY,JSON.stringify(state));}catch{toast('Seu navegador não permitiu salvar o progresso.',true);}};
function toast(message,error=false){const t=document.createElement('div');t.className='toast '+(error?'error':'');t.innerHTML=I(error?'info':'check')+`<span>${esc(message)}</span>`;$('#toast-root').append(t);setTimeout(()=>t.remove(),4500);}
const sprite=renderRobotSprite;
function partArt(p){const asset=partAsset(p);return `<span class="part-emblem"><img src="${assetUrl(asset)}" alt="${esc(p?.name||'Equipamento')}" decoding="async"></span>`;}

const isAdmin=()=>API.isDemo||state.profile.role==='admin'||state.profile.isAdmin===true;
const selected=()=>state.robots.find(r=>r.uid===state.selectedRobot)||state.robots[0];
const selectedInfo=()=>selected()?C.robotInfo(state,selected()):null;
const realValue=(currency,amount)=>currency==='LC'?amount/state.settings.lcPerReal:amount/state.settings.rcPerLC/state.settings.lcPerReal;
const stats=()=>state.robots.map(r=>C.robotInfo(state,r));
function heading(kicker,title,body='',tools=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1>${body?`<p>${body}</p>`:''}</div>${tools}</div>`;}
function modal(html,cls=''){if(typeof mediaAdmin!=='undefined'){html=html.replace(/(<select name="asset"[^>]*>[\s\S]*?<\/select>)/g,whole=>whole+mediaAdmin.fileInput('asset'));}modalFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${cls}" role="dialog" aria-modal="true" aria-labelledby="modal-title">${combat||matchmaking?'':`<button class="modal-close icon-btn" data-a="close" aria-label="Fechar">${I('close')}</button>`}${ui(html)}</section></div>`;document.body.classList.add('modal-open');setTimeout(()=>$('#modal-root button, #modal-root input')?.focus(),20);}
function closeModal(){if(combat)return;if(matchmaking){arenaQueue.cancel();return;}$('#modal-root').innerHTML='';document.body.classList.remove('modal-open');modalFocus?.focus?.();}
function confirmModal(title,body,label,action,extra=''){modal(`<div class="modal-emblem">${I('spark')}</div><h2 id="modal-title">${title}</h2><p>${body}</p><div class="modal-actions">${btn(label,action,extra)}${btn('Voltar','close','','secondary')}</div>`);}
function render(){
 document.documentElement.style.setProperty('--accent',visibleAccent(state.settings.accent));
 if(page==='login'){renderLogin();floatingChat.refresh();return;}
 const dock=[['home',state.settings.copy.hangarLabel,'home'],['robots',state.settings.copy.robotsLabel||'Meus robôs','robot'],['story',state.settings.copy.storyLabel,'story'],['arena',state.settings.copy.arenaLabel,'arena'],['shop',state.settings.copy.shopLabel,'shop'],['wallet',state.settings.copy.walletLabel,'wallet'],['affiliates',state.settings.copy.networkLabel||'Rede','users']];
 $('#app').innerHTML=ui(`<div class="app-shell game-app"><div class="workspace"><header class="game-header"><div class="game-header-top"><a class="brand game-brand" href="#home"><span class="brand-mark game-crest"><img src="${assetUrl(state.settings.logoArt||'game-mark.png')}" alt="Emblema do LifeBots"></span><span>${esc(state.settings.name)}<small>${copy('authTagline','UMA NOVA ERA')}</small></span></a><span class="release-tag">NOVO VISUAL <b>v${GAME_VERSION}</b></span><button class="pilot-hud" data-a="profile"><span class="avatar pilot-portrait">${selectedInfo()?sprite(selectedInfo()):I('robot')}</span><span><b>${esc(state.profile.name)}</b><small>NV. ${state.profile.level}</small></span></button></div><div class="game-balances"><div class="wallet-chip rc-chip">${coin('RC')}<span><small>RobotCoins</small><b>${n(state.balances.RC)}</b></span><button data-a="convert" aria-label="Converter RobotCoins">${I('plus')}</button></div><div class="wallet-chip lc-chip">${coin('LC')}<span><small>LifeCoins</small><b>${n(state.balances.LC)}</b></span><button data-a="deposit" aria-label="Adicionar LifeCoins">${I('plus')}</button></div><button class="notice-hud" data-a="notifications" aria-label="Novidades">${I('bell')}<i></i></button></div><div class="game-meta"><button data-a="account-info"><i></i>CONTA CONECTADA</button><button data-a="install">${I('download')} Instalar</button><button data-a="sound-toggle" class="sound-toggle" aria-pressed="${audio.preferences.enabled}">${I('volume')}<span class="sound-toggle-label">${audio.preferences.enabled?'Som ativado':'Ativar som'}</span></button><button data-a="sound-settings">Mix de áudio</button><button data-a="floating-chat-open" aria-label="Reabrir chat flutuante">${I('users')} Chat</button></div></header><main id="main-content" class="content ${page==='home'?'home-content':''} ${page==='admin'?'admin-content':''}">${renderPage()}</main><footer class="footer"><span>LifeBots <em>·</em> v${GAME_VERSION}</span><button data-a="demo-info">${I('info')} ${API.isDemo?'Sobre a prévia':'Sobre o jogo'}</button></footer></div></div><nav class="bottom-nav game-dock" aria-label="Navegação do jogo">${dock.map(([id,t,i])=>`<a href="#${id}" class="${page===id?'active':''}">${I(i)}<span>${t}</span>${id==='arena'?`<small>${C.dailyBattles(state)}</small>`:''}</a>`).join('')}<button data-a="mobile-menu" class="${['admin','guilds','market','chat','events'].includes(page)?'active':''}">${I('settings')}<span>${copy('moreLabel','Mais')}</span></button></nav>`);
 $('#main-content')?.setAttribute('data-page',page);floatingChat.refresh();tick();syncAudioScene();if(!combat&&!matchmaking&&!['admin','login'].includes(page)&&state.settings.announcementActive!==false&&state.settings.announcementPopup&&(state.settings.announcementVersion||0)>(state.seenAnnouncementVersion||0)){state.seenAnnouncementVersion=state.settings.announcementVersion;save();audio.play('notification');setTimeout(()=>modal(`<span class="eyebrow">AVISO DO HANGAR</span><h2 id="modal-title">${esc(state.settings.announcement)}</h2>${state.settings.announcementImage?`<img class="announcement-img" src="${esc(safeUrl(state.settings.announcementImage))}" alt="Aviso do hangar">`:''}<p>${esc(state.settings.announcementBody)}</p><a class="btn primary wide" href="${esc(safeUrl(state.settings.announcementLink))}" data-a="close">${esc(state.settings.announcementButton)}</a>`),100);}
}

function renderPage(){if(!remoteLoaded&&!API.isDemo)return `<div class="empty"><h2>Conecte sua conta</h2><p>Acesso e dados são carregados pelo Supabase.</p>${btn('Entrar','login')}</div>`;return ({home:home,robots:robots,story:story,arena:arena,shop:shop,wallet:wallet,affiliates:affiliates,guilds:()=>socialView.guilds(),market:()=>socialView.market(),chat:()=>socialView.chat(),events:()=>socialView.events(),admin:admin}[page]||home)();}
function robotCard(r,compact=false){const v=C.robotInfo(state,r);return `<article class="robot-card ${compact?'compact':''}" style="--robot-color:${v.color}"><div class="robot-art"><span class="rarity ${v.rarity.toLowerCase()}">${esc(v.rarity)}</span><span class="level">NV. ${v.level}</span><div class="robot-grid"></div>${sprite(v)}<div class="robot-shadow"></div><span class="robot-status ${v.active?'':'expired'}"><i></i>${v.active?'Em atividade':'Prazo encerrado'}</span></div><div class="robot-card-body"><div class="robot-card-title"><h3>${esc(v.name)}</h3><span>${v.type==='explorer'?'Explorador':v.type==='striker'?'Atacante':'Guardião'}</span></div><p class="owned-identity">${esc(v.subtitle||'Companheiro de Aurora')}</p><div class="production"><span>Produção diária</span><b>${coin('RC')}${n(v.daily)} <small>RC</small></b></div><div class="owned-yield-estimate">≈ ${approximateBRL(realValue('RC',v.daily))} / dia na cotação atual</div><div class="robot-meta"><span>${I('clock')}${Math.max(0,Math.ceil((v.expires-Date.now())/C.DAY))} dias restantes</span><span>${I('arena')}${v.remainingBattles} usos</span></div>${compact?'':`<div class="owned-return">${coin('LC')}<span>${r.principalReturnedAt?'Devolvido':'Ao expirar'}: <b>${n(v.principalReturnLC)} LC</b></span></div><div class="robot-detail-stats"><div><small>Batalhas realizadas</small><b>${n(v.used)}</b></div><div><small>Total produzido</small><b>${n(v.earned)} RC</b></div><div><small>Peças equipadas</small><b>${v.equipment.length}/${v.contract?.slots?.length||v.slots?.length||3}</b></div><div><small>Disponível agora</small><b>${n(v.available)} RC</b></div></div>`}<div class="card-actions">${btn('Ver robô '+I('arrow'),'robot-detail',`data-id="${r.uid}"`,'secondary')}${!compact?btn(I('bolt')+' Evoluir','upgrade',`data-id="${r.uid}"`):''}</div></div></article>`;}
function home(){const list=stats(),sel=selectedInfo(),daily=list.filter(r=>r.active).reduce((sum,r)=>sum+r.daily,0),ready=list.reduce((sum,r)=>sum+r.available,0),chapters=C.chapters(state),next=chapters[Math.min(state.story,chapters.length-1)],playable=state.activeStory&&!state.activeStory.settled&&state.activeStory.status!=='cancelled'?state.activeStory.chapter:sel&&sel.power>=next.power?next:chapters.filter(c=>c.id<=state.story&&sel&&c.power<=sel.power).at(-1)||chapters[0],season=C.seasons(state).find(s=>s.from<=next.id&&s.to>=next.id)||C.seasons(state)[0];
 return `<section class="hangar-stage"><div class="hangar-vignette"></div><div class="hangar-title"><span class="eyebrow">TEMPORADA ${String(season.number||1).padStart(2,'0')} · ${esc(season.title)}</span><h1>${copy('homeTitle','Hangar principal')}</h1><p>${esc(state.settings.heroSubtitle)}</p></div><div class="stage-world-status"><i></i>${list.filter(r=>r.active).length} ROBÔS ATIVOS</div><div class="hangar-crew" aria-label="Sua equipe no hangar">${list.filter(r=>r.uid!==sel?.uid).slice(0,4).map((r,i)=>`<button class="hangar-crew-member crew-${i} ${r.active?'':'inactive'}" data-a="select-hangar" data-id="${r.uid}" title="Selecionar ${esc(r.name)}">${sprite(r)}<span>${esc(r.name)}<small>NV. ${r.level}</small></span></button>`).join('')}</div><div class="hangar-actor">${sel?sprite(sel,'hangar-sprite'):''}<div class="actor-platform"></div></div><button class="actor-nav prev" data-a="cycle-robot" data-id="-1" aria-label="Robô anterior">${I('chevron')}</button><button class="actor-nav next" data-a="cycle-robot" data-id="1" aria-label="Próximo robô">${I('chevron')}</button><aside class="stage-panel stage-quest"><div class="quest-map-preview"></div><span class="eyebrow">SUA PRÓXIMA MISSÃO</span><h2>${esc(next.title)}</h2><p>${esc(next.place)}</p><div class="quest-prize">${coin('RC')}<b>${n(next.reward)} RC</b><span>Prêmio do capítulo</span></div>${btn('Ver o mapa '+I('arrow'),'goto','data-page="story"','secondary wide')}</aside><aside class="stage-panel stage-collector"><span class="eyebrow">ENERGIA DA EQUIPE</span><div class="collector-orb">${coin('RC')}<span class="orb-ring"></span></div><div class="collector-rate"><b>${n(daily)}</b><span>RC / dia</span></div><p>Seus robôs estão produzindo.</p><div class="collector-ready"><span>Disponível</span><b data-live-collect>${n(ready)} RC</b></div>${btn('Coletar agora '+I('download'),'collect','','primary wide')}</aside><div class="actor-caption"><span class="rarity">${esc(sel?.rarity||'Hangar vazio')}</span><div class="actor-name"><h2>${esc(sel?.name||'Seu primeiro robô')}</h2><span>NV. ${sel?.level||1}</span></div><div class="actor-attributes"><span>${I('bolt')} ${sel?.power||0} poder</span><span>${I('arena')} ${sel?.attack||0} ataque</span><span>${I('shield')} ${sel?.defense||0} defesa</span></div>${sel?btn('Equipar / evoluir','robot-detail',`data-id="${sel.uid}"`,'text'):btn('Adquirir robô','goto','data-page="shop"')}</div><div class="hangar-actions">${btn(I('story')+(state.activeStory&&!state.activeStory.settled&&state.activeStory.status!=='cancelled'?' Retomar expedição':playable.id<=state.story?' Rejogar aventura':' Explorar capítulo'),'chapter',`data-id="${playable.id}"`,'primary adventure-button')}${btn(I('arena')+' Arena <span>'+C.dailyBattles(state)+' batalhas</span>','goto','data-page="arena"','secondary arena-button')}</div><span class="scene-coordinates">SETOR AURORA · 01</span></section><div class="squad-heading"><h2>Sua equipe</h2><a href="#robots">Gerenciar robôs ${I('chevron')}</a></div><div class="squad-bar">${state.robots.map(r=>{const v=C.robotInfo(state,r);return `<button class="squad-slot ${r.uid===selected()?.uid?'selected':''}" data-a="select-hangar" data-id="${r.uid}"><span class="squad-level">NV. ${r.level}</span>${sprite(v)}<b>${esc(v.name)}</b><small>${v.active?n(v.daily)+' RC/dia':'Prazo encerrado'}</small></button>`;}).join('')}<button class="squad-slot add-squad" data-a="goto" data-page="shop"><span>${I('plus')}</span><b>Novo robô</b><small>Explorar oficina</small></button></div><div class="game-shortcuts"><button data-a="tutorial">${I('gift')}<span><b>${state.profile.tutorial?'Tutorial concluído':'Bônus de boas-vindas'}</b><small>${state.profile.tutorial?'Revise as regras do universo':'Resgate '+n(state.settings.tutorialBonus)+' LifeCoins'}</small></span>${coin('LC')}</button><button data-a="goto" data-page="shop">${I('core')}<span><b>Melhore seu robô</b><small>Novas peças na oficina</small></span><img src="${assetUrl('plasma-core.png')}" alt="Núcleo de plasma"></button></div>`;
}

function robots(){return `${heading('SUA EQUIPE',copy('robotsTitle','Pequenos robôs. Grandes histórias.'),'Acompanhe o tempo de vida, os equipamentos e cada conquista.',btn(I('plus')+' Adquirir robô','goto','data-page="shop"'))}<div class="filter-bar"><span class="pill active">Todos (${state.robots.length})</span><span class="subtle">${stats().filter(x=>x.active).length} em atividade</span><button class="text-btn" data-a="collect">${I('core')} Coletar de todos</button></div><div class="robot-grid-list">${state.robots.length?state.robots.map(r=>robotCard(r)).join(''):'<div class="empty">Seu primeiro robô está esperando na oficina.</div>'}</div>`;}
function story(){return storyMap.render();}
function robotSelector(){return renderRobotPicker({state,core:C,sprite,escape:esc,icon:I});}
function arena(){const sel=selectedInfo();return `${heading('ARENA',copy('arenaTitle','Encontre seu próximo adversário.'),copy('arenaDescription','Entre na fila com seu robô e prepare sua estratégia.'),btn(I('plus')+' Passe extra · '+n(state.settings.passCost)+' LC','buy-pass','','secondary'))}<div class="arena-top"><div class="arena-allowance"><div class="arena-symbol">${I('arena')}</div><div><small>SUAS BATALHAS DE HOJE</small><b>${C.dailyBattles(state)} <span>disponíveis</span></b><p>${state.settings.freeBattles} gratuitas por dia · reinício à meia-noite de Brasília</p></div></div>${robotSelector()}</div><section class="pvp-arena-stage"><div class="pvp-player">${sel?sprite(sel):''}<span class="eyebrow">SEU ROBÔ</span><h2>${sel?esc(sel.name):'Selecione um robô'}</h2><p>NV. ${sel?.level||1} · ${sel?.power||0} de poder</p></div><div class="pvp-emblem">${I('arena')}<b>VS</b><small>Jogador × Jogador</small></div><div class="pvp-rival"><div class="pvp-rival-silhouette">${I('robot')}</div><span class="eyebrow">SEU ADVERSÁRIO</span><h2>Quem será o próximo?</h2><p>Seu próximo desafio na arena</p></div></section><div class="pvp-search-panel"><div><h2>Pronto para a arena?</h2><p>Buscamos outro jogador por até ${state.settings.matchTimeoutSeconds||8}s. Sem um par disponível, um adversário controlado pelo jogo assume o desafio.</p></div>${btn(I('arena')+' Buscar batalha','find-match','','primary')}</div><div class="pvp-rules"><span>${coin('RC')} Vitória <b>+${state.settings.battleReward} RC</b></span><span>${coin('RC')} Derrota <b>−${state.settings.battleLoss} RC</b></span><small>1 chance diária + 1 uso do robô apenas quando a batalha começa.</small></div>${API.isDemo?`<div class="notice">${I('info')} Esta prévia usa adversários controlados pelo jogo. Entre na sua conta para encontrar outros pilotos.</div>`:''}<div class="section-title"><h2>Últimas batalhas</h2></div>${state.battles.length?`<div class="table-wrap"><table><thead><tr><th>Adversário</th><th>Resultado</th><th>RobotCoins</th><th>Data</th></tr></thead><tbody>${state.battles.slice(0,10).map(b=>`<tr><td>${esc(b.opponent)}</td><td><span class="status ${b.win?'good':'bad'}">${b.win?'Vitória':'Derrota'}</span></td><td>${b.amount>0?'+':''}${n(b.amount)} RC</td><td>${new Date(b.at).toLocaleDateString('pt-BR')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty small">Sua primeira batalha será o início dessa história.</div>'}`;}

function shop(){return `${heading('OFICINA',copy('shopTitle','Construa sua próxima versão.'),copy('shopDescription','Robôs, peças e novas possibilidades para a sua equipe.'))}<div class="tabs"><button class="${shopTab==='robots'?'active':''}" data-a="shop-tab" data-id="robots">${I('robot')} Novos robôs</button><button class="${shopTab==='parts'?'active':''}" data-a="shop-tab" data-id="parts">${I('core')} Equipamentos</button><button class="${shopTab==='inventory'?'active':''}" data-a="shop-tab" data-id="inventory">${I('shop')} Meu inventário <small>${state.inventory.length}</small></button></div>${shopTab==='robots'?`<div class="catalog-grid">${state.catalog.map(r=>`<article class="catalog-card" style="--robot-color:${r.color}"><div class="catalog-art"><span class="rarity ${r.rarity.toLowerCase()}">${esc(r.rarity)}</span>${sprite(r)}<div class="catalog-ring"></div></div><div class="catalog-body"><div class="catalog-identity"><small>${esc(r.serial||'')} · ${{explorer:'EXPLORADOR',striker:'ATACANTE',guardian:'GUARDIÃO'}[r.type]}</small><h2>${esc(r.name)}</h2><span>${esc(r.subtitle||'')}</span></div><p>${esc(r.description)}</p><div class="catalog-stats"><span>${I('bolt')} <b>${r.attack} ataque</b></span><span>${I('clock')} ${r.lifetime} dias</span><span>${I('arena')} ${r.maxBattles} batalhas</span></div>${robotOffers.projection(r,true)}<div class="purchase-row"><div>${coin(r.currency)}<b>${n(r.price)} ${r.currency}</b><small>≈ ${approximateBRL(robotOffer(state,r).priceBRL)}</small></div>${btn('Adquirir '+I('plus'),'buy-robot',`data-id="${esc(r.id)}"`)}</div></div></article>`).join('')}</div>`:shopTab==='parts'?`<div class="parts-grid">${state.parts.map(p=>`<article class="part-card equipment-game-card" data-rarity="${esc(p.rarity||'Comum')}"><div class="equipment-showcase"><span class="rarity">${esc(p.rarity||'Comum')}</span>${partArt(p)}<div class="equipment-orbit"></div></div><small>${{core:'NÚCLEO',arm:'BRAÇO',shield:'ESCUDO',booster:'PROPULSOR',sensor:'SENSOR'}[p.slot]} · NV. ${p.level}</small><h3>${esc(p.name)}</h3><strong class="equipment-subtitle">${esc(p.subtitle||'Peça para sua próxima evolução')}</strong><p>${esc(p.description)}</p><div class="part-effects"><span>+${p.production}% produção</span><span>+${p.attack} ataque</span><span>+${p.defense} defesa</span></div><div class="compatibility">Compatível: ${p.compatible.map(t=>({explorer:'Explorador',striker:'Atacante',guardian:'Guardião'}[t]||esc(t))).join(', ')}</div><div class="purchase-row"><b>${coin(p.currency)} ${n(p.price)} ${p.currency}</b>${btn('Adquirir','buy-part',`data-id="${esc(p.id)}"`,'secondary')}</div></article>`).join('')}</div>`:`<div class="parts-grid">${state.inventory.map(i=>{const p=state.parts.find(x=>x.id===i.partId);return `<article class="part-card equipment-game-card" data-rarity="${esc(p.rarity||'Comum')}"><div class="equipment-showcase"><span class="rarity">${esc(p.rarity||'Comum')}</span>${partArt(p)}<div class="equipment-orbit"></div></div><small>EQUIPAMENTO · NV. ${i.level}</small><h3>${esc(p?.name)}</h3><p>${i.equippedOn?'Equipada em '+esc(C.robotInfo(state,state.robots.find(x=>x.uid===i.equippedOn)).name):'Pronta para equipar'}</p><div class="card-actions">${btn('Equipar','equip-modal',`data-id="${i.uid}"`,'secondary')}${btn('Evoluir','upgrade-part',`data-id="${i.uid}"`,'secondary')}</div></article>`;}).join('')||'<div class="empty">Seu inventário está vazio. Encontre suas primeiras peças na oficina.</div>'}</div>`}`;}
function wallet(){const total=realValue('LC',state.balances.LC)+realValue('RC',state.balances.RC);return `${heading('SUA CARTEIRA',copy('walletTitle','Tudo em um só lugar.'),`LifeCoins para adquirir. RobotCoins para evoluir. ${API.isDemo?'Valores fictícios nesta prévia.':'Saldos e movimentações confirmados pelo servidor.'}`)}<div class="wallet-overview"><div><span class="eyebrow">${API.isDemo?'VALOR EQUIVALENTE DE TESTE':'VALOR ESTIMADO EM REAIS'}</span><h2>${brl(total)}</h2><small>LC + RC na cotação atual</small></div><div class="wallet-overview-actions">${btn(I('plus')+' Depositar','deposit')}${btn(I('arrow')+' Sacar','withdraw','','secondary')}${btn(I('core')+' Converter','convert','','secondary')}</div></div><div class="currency-cards"><article><div class="currency-head">${coin('LC')}<div><h3>LifeCoins</h3><p>Moeda de aquisição</p></div><span>LC</span></div><strong>${n(state.balances.LC)} <small>LC</small></strong><div class="currency-row"><span>Equivalente estimado em reais</span><b>${brl(realValue('LC',state.balances.LC))}</b></div><div class="currency-row"><span>Conversão de compra</span><b>R$ 1 = ${n(state.settings.lcPerReal)} LC</b></div></article><article><div class="currency-head">${coin('RC')}<div><h3>RobotCoins</h3><p>Produção e recompensas</p></div><span>RC</span></div><strong>${n(state.balances.RC)} <small>RC</small></strong><div class="currency-row"><span>Equivalente estimado em reais</span><b>${brl(realValue('RC',state.balances.RC))}</b></div><div class="currency-row"><span>Conversão interna</span><b>${n(state.settings.rcPerLC)} RC = 1 LC</b></div></article></div><div class="wallet-rules"><div><h3>${I('info')} Regras de conversão e saque</h3><p>${esc(state.settings.withdrawalRules)}</p><div class="rules-chips"><span>Mínimo: ${brl(state.settings.minWithdraw)}</span><span>Taxa: ${state.settings.withdrawFee}%</span></div></div><div class="deposit-total"><small>${API.isDemo?'Depósitos simulados':'Depósitos confirmados'}</small><b>${brl(state.depositedCents/100)}</b><small>${API.isDemo?'Saques simulados':'Saques concluídos'}: ${brl(state.withdrawnCents/100)}</small><small>Reservado para saques: ${n(state.reservedLC||0)} LC</small></div></div><div class="expiry-wallet-panel">${coin('LC')}<div><h3>O valor de aquisição volta em LC</h3><p>Ao encerrar o prazo, cada robô devolve o valor previsto no seu contrato. A cotação fica registrada na aquisição; a devolução é automática e aparece no extrato. Peças e evoluções não são devolvidas como LC.</p><b>${n(state.robots.filter(r=>r.principalReturnedAt==null).reduce((sum,r)=>sum+(r.contract?.principalReturnLC??r.principalReturnLC??0),0))} LC previstas nos robôs da equipe</b></div></div><div class="section-title"><h2>Suas movimentações</h2><span class="subtle">${API.isDemo?'Extrato demonstrativo':'Extrato da conta'}</span></div>${transactionTable(state.transactions)}`;}
function transactionTable(items){return `<div class="table-wrap"><table><thead><tr><th>Movimentação</th><th>Quantidade</th><th>Status</th><th>Quando</th></tr></thead><tbody>${items.slice(0,30).map(t=>`<tr><td><span class="transaction-icon">${I(t.amount>=0?'download':'arrow')}</span>${esc(t.kind)}</td><td class="${t.amount>=0?'positive':''}">${coin(t.currency)} ${t.amount>0?'+':''}${n(t.amount)} ${esc(t.currency)}</td><td><span class="status">${esc(t.status)}</span></td><td>${new Date(t.at).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'})}</td></tr>`).join('')||'<tr><td colspan="4">Nenhuma movimentação.</td></tr>'}</tbody></table></div>`;}

function affiliates(){return referralView.render();}
function input(label,key,value,type='text',props=''){return `<label class="form-field"><span>${label}</span><input name="${key}" type="${type}" value="${esc(value)}" ${props}></label>`;}
function textarea(label,key,value){return `<label class="form-field full"><span>${label}</span><textarea name="${key}" rows="3">${esc(value)}</textarea></label>`;}
function admin(){return isAdmin()?adminStudio({state,tab:adminTab,body:adminBody(),escape:esc,icon:I,assetUrl}):'<div class="empty">Acesso restrito aos administradores.</div>';}
function adminBody(){if(!isAdmin())return '<div class="empty">Acesso restrito aos administradores.</div>';const s=state.settings;return `${heading('PAINEL ADMINISTRATIVO','O universo, do seu jeito.',API.isDemo?'As alterações de teste são salvas neste navegador.':'Gestão autenticada pelo servidor.',API.isDemo?btn(I('clock')+' Simular 1 dia','simulate-day','','secondary'):'')}<div class="tabs admin-tabs">${[['guild-admin','Guildas e eventos'],['trade-admin','Trading'],['chat-admin','Chat'],['users','Usuários'],['deposits','Depósitos'],['withdrawals','Saques'],['notices','Avisos globais'],['economy','Economia'],['robots','Robôs'],['parts','Peças e compatibilidade'],['campaign','Campanha e temporadas'],['arena-config','Adversários'],['combat','Combate e progressão'],['audio','Sons'],['copy','Textos'],['layout','Visual e mensagens'],['media','Imagens e sons'],['activity','Atividade']].map(([id,t])=>`<button data-a="admin-tab" data-id="${id}" class="${adminTab===id?'active':''}">${t}</button>`).join('')}</div>${adminTab==='economy'?`<form id="admin-economy" class="admin-form"><section><h3>${I('wallet')} Moedas e carteira</h3><div class="form-grid">${input('Multiplicador de produção (1 a 100)','productionMultiplier',s.productionMultiplier,'number','min="1" max="100" step="0.1" required')}${input('Devolução da aquisição ao expirar (%)','principalReturnPercent',s.principalReturnPercent,'number','min="0" max="100" step="0.1" required')}${input('LifeCoins por R$ 1','lcPerReal',s.lcPerReal,'number','min="1" required')}${input('RobotCoins por LifeCoin','rcPerLC',s.rcPerLC,'number','min="1" required')}${input('Saque mínimo (R$)','minWithdraw',s.minWithdraw,'number','min="0.01" step="0.01" required')}${input('Taxa de saque (%)','withdrawFee',s.withdrawFee,'number','min="0" max="100" step="0.01" required')}${input('Bônus do tutorial (LC)','tutorialBonus',s.tutorialBonus,'number','min="0" required')}${input('Custo base de evolução (RC)','levelCost',s.levelCost,'number','min="1" required')}${input('Nível máximo do robô','maxRobotLevel',s.maxRobotLevel||10,'number','min="1" required')}${input('Nível máximo de peça','maxPartLevel',s.maxPartLevel||10,'number','min="1" required')}</div></section><section><h3>${I('arena')} Arena</h3><div class="form-grid">${input('Batalhas gratuitas por dia','freeBattles',s.freeBattles,'number','min="0" required')}${input('Preço do passe extra (LC)','passCost',s.passCost,'number','min="1" required')}${input('Recompensa por vitória (RC)','battleReward',s.battleReward,'number','min="1" required')}${input('Perda máxima por derrota (RC)','battleLoss',s.battleLoss,'number','min="0" required')}${input('Espera na fila antes do bot (segundos)','matchTimeoutSeconds',s.matchTimeoutSeconds||8,'number','min="3" max="60" required')}</div></section><section><h3>${I('users')} Comissão por produção diária</h3><div class="form-grid thirds">${s.commissions.map((v,i)=>input(`Nível ${i+1} (%)`,'commission'+i,v,'number','min="0" max="100" step="0.01" required')).join('')}</div><p class="subtle">Calculada sobre as recompensas efetivamente creditadas dos robôs dos afiliados.</p></section><button class="btn primary" type="submit">${I('check')} Salvar configurações</button></form>`:
adminTab==='layout'?`<form id="admin-layout" class="admin-form"><section><h3>${I('eye')} Aparência</h3><div class="form-grid">${input('Nome do jogo','name',s.name,'text','maxlength="60"')}${input('Cor de destaque','accent',s.accent,'color')}${input('Nome do guia','guideName',s.guideName,'text','maxlength="40"')}${['hangarBackground','authBackground'].map(k=>`<label class="form-field"><span>${k==='hangarBackground'?'Cenário do hangar':'Cenário do login'}</span><select name="${k}">${['hangar','ember','frost','sky','space'].map(x=>`<option value="${x}" ${s[k]===x?'selected':''}>${x}</option>`).join('')}</select></label>`).join('')}${[0,1,2].map(i=>`<label class="form-field"><span>Robô ${i+1} do login</span><select name="authRobot${i}">${state.catalog.map(r=>`<option value="${esc(r.id)}" ${s.authRobotIds[i]===r.id?'selected':''}>${esc(r.name)}</option>`).join('')}</select></label>`).join('')}<label class="form-field"><span>Fundo do universo</span><select name="worldBackground">${C.SCENES.map(x=>`<option value="${x}" ${s.worldBackground===x?'selected':''}>${x}</option>`).join('')}</select></label>${input('Intensidade do fundo (0 a 1)','backgroundIntensity',s.backgroundIntensity,'number','min="0" max="1" step="0.05"')}<label class="checkbox"><input name="visualMotion" type="checkbox" ${s.visualMotion?'checked':''}> Movimento e partículas no universo</label><label class="checkbox"><input name="battleAtmosphere" type="checkbox" ${s.battleAtmosphere?'checked':''}> Atmosfera nas batalhas</label>${input('Frase do universo','tagline',s.tagline)}<label class="form-field"><span>Composição do hangar</span><select name="layout"><option value="cinematic" ${s.layout==='cinematic'?'selected':''}>Cenário cinematográfico</option><option value="compact" ${s.layout==='compact'?'selected':''}>Hangar compacto</option></select></label></div>${textarea('Texto principal','heroSubtitle',s.heroSubtitle)}<div class="form-grid">${[['logoArt','Logo do jogo'],['worldBackgroundArt','Fundo do universo'],['hangarBackgroundArt','Fundo do hangar'],['authBackgroundArt','Fundo de login']].map(([k,label])=>mediaAdmin.picker(label,k,s[k]||'')).join('')}</div></section><section><h3>${I('bell')} Aviso aos pilotos</h3><div class="form-grid">${input('Título do aviso','announcement',s.announcement)}${input('Texto do botão','announcementButton',s.announcementButton)}${input('Link do botão','announcementLink',s.announcementLink)}${input('URL da imagem opcional','announcementImage',s.announcementImage)}</div>${textarea('Mensagem','announcementBody',s.announcementBody)}</section><section><h3>Regras exibidas na carteira</h3>${textarea('Regras de saque e conversão','withdrawalRules',s.withdrawalRules)}</section><button class="btn primary" type="submit">${I('check')} Salvar visual e mensagens</button></form>`:
adminTab==='robots'?`<div class="section-title"><h2>Catálogo de robôs</h2>${btn(I('plus')+' Novo robô','edit-robot','data-id="new"')}</div><div class="admin-catalog">${state.catalog.map(r=>`<article>${sprite(r)}<div><h3>${esc(r.name)}</h3><p>${r.price} ${r.currency} · ${Math.floor(r.daily*(state.settings.productionMultiplier??1))} RC/dia · ${r.lifetime} dias · ${r.maxBattles} batalhas</p><small>${esc(r.type)} / ${esc(r.rarity)}</small></div>${btn('Editar','edit-robot',`data-id="${esc(r.id)}"`,'secondary')}${btn('Excluir','delete-robot',`data-id="${esc(r.id)}"`,'text')}</article>`).join('')}</div>`:
adminTab==='media'?mediaAdmin.render():
adminTab==='parts'?`<div class="section-title"><h2>Equipamentos e compatibilidade</h2>${btn(I('plus')+' Nova peça','edit-part','data-id="new"')}</div><div class="admin-catalog">${state.parts.map(p=>`<article>${partArt(p)}<div><h3>${esc(p.name)}</h3><p>${p.price} ${p.currency} · +${p.production}% produção</p><small>${p.compatible.map(esc).join(', ')}</small></div>${btn('Editar','edit-part',`data-id="${esc(p.id)}"`,'secondary')}${btn('Excluir','delete-part',`data-id="${esc(p.id)}"`,'text')}</article>`).join('')}</div>`:socialAdmin.handles(adminTab)?socialAdmin.render(adminTab):adminOperations.handles(adminTab)?adminOperations.render(adminTab):contentAdmin.handles(adminTab)?contentAdmin.render(adminTab):`<div class="admin-activity"><div class="notice">${I('info')} Atividade e movimentações da conta.</div><div class="section-title"><h2>Movimentações (${state.transactions.length})</h2>${btn('Exportar estado JSON','export-state','','secondary')}</div>${transactionTable(state.transactions)}</div>`}`;}
function renderLogin(){audio.setScene('login');$('#app').innerHTML=ui(loginView.render(authMode));}
async function mutate(localFn,message,remote,{keepGame=false,sound=null}={}){try{let result;if(!API.isDemo){if(!remote)throw new Error('Esta ação não está disponível neste modo de jogo.');const reply=await API.action(remote.action,remote.payload);result=reply.data?.result??reply.data??reply;if(reply.data?.snapshot)absorbRemote(reply.data.snapshot);else await loadRemote();}else{const candidate=C.clone(state);result=localFn(candidate);state=candidate;save();}if(keepGame)floatingChat.refresh();else{closeModal();render();}if(message)toast(typeof message==='function'?message(result):message);const cue=sound||successfulActionSound(remote?.action,result,remote?.payload);if(cue){await audio.unlock();audio.play(cue);}return true;}catch(e){toast(e.message,true);return false;}}
function robotDetail(uid){const r=state.robots.find(x=>x.uid===uid);if(!r)return;const v=C.robotInfo(state,r);modal(`<div class="detail-art" style="--robot-color:${v.color}">${sprite(v)}<span class="rarity">${esc(v.rarity)}</span></div><span class="eyebrow">${esc(v.type)} · NV. ${v.level}</span><h2 id="modal-title">${esc(v.name)}</h2><p>${esc(v.description)}</p><div class="detail-grid"><div><small>Produção diária</small><b>${v.daily} RC</b><small>≈ ${approximateBRL(realValue('RC',v.daily))} / dia</small></div><div><small>Total produzido</small><b>${v.earned} RC</b></div><div><small>Prazo restante</small><b>${Math.max(0,Math.ceil((v.expires-Date.now())/C.DAY))} dias</b></div><div><small>Batalhas restantes</small><b>${v.remainingBattles} / ${v.maxBattles}</b></div><div><small>Poder</small><b>${v.power}</b></div><div><small>Usos na arena</small><b>${v.used}</b></div></div><div class="acquisition-return">${coin('LC')}<div><b>${n(v.principalReturnLC)} LC ${r.principalReturnedAt?'devolvidas à carteira':'de devolução ao encerrar o prazo'}</b><small>Valor congelado na aquisição · equipamentos e evoluções separados</small></div></div>${equipmentView.slots(v)}<div class="modal-actions">${btn('Evoluir · '+state.settings.levelCost*r.level+' RC','upgrade',`data-id="${uid}"`)}${btn('Usar na arena','select-arena',`data-id="${uid}"`,'secondary')}${btn('Coletar '+v.available+' RC','collect-one',`data-id="${uid}"`,'secondary')}</div>`,'robot-modal');}
function moneyModal(kind){const dep=kind==='deposit';modal(`<div class="modal-emblem">${I(dep?'plus':'wallet')}</div><span class="eyebrow">${API.isDemo?'OPERAÇÃO DE TESTE':'CARTEIRA · PIX'}</span><h2 id="modal-title">${dep?'Mais energia para sua equipe.':'Solicitar saque.'}</h2><p>${dep?`R$ 1 = ${state.settings.lcPerReal} LifeCoins. O crédito acontece após a confirmação do pagamento.`:'A cotação e a taxa ficam registradas ao solicitar. O valor é reservado até a conclusão.'}</p><form id="money-form" data-kind="${kind}" data-request-key="${C.uuid()}">${input('Valor (R$)','amount',dep?'20':String(state.settings.minWithdraw),'number',`min="${dep?.01:state.settings.minWithdraw}" step="0.01" required`)}${dep?`<div class="quick-amounts">${[10,20,50,100].map(v=>`<button type="button" data-a="amount" data-id="${v}">R$ ${v}</button>`).join('')}</div>`:!API.isDemo?`<label class="form-field"><span>Tipo da chave Pix</span><select name="pix_key_type">${['cpf','cnpj','email','phone','evp'].map(x=>`<option value="${x}">${({phone:'Telefone',evp:'Aleatória'})[x]||x.toUpperCase()}</option>`).join('')}</select></label>${input('Chave Pix','pix_key','','text','required maxlength="200"')}${input('CPF/CNPJ do titular','recipient_document','','text','maxlength="18"')}`:''}<div class="quote-box" id="money-quote"></div><div class="notice">${I('info')}${API.isDemo?'Operação fictícia, somente nesta demonstração.':'Pagamento via Pix. O saldo é atualizado após a confirmação.'}</div><button type="submit" class="btn primary wide">${API.isDemo?(dep?'Simular depósito':'Simular saque'):(dep?'Gerar Pix':'Solicitar saque')}</button></form>`);updateQuote();}
function paymentView(payment){modal(`<span class="eyebrow">${payment.kind==='deposit'?'DEPÓSITO':'SAQUE'} · PIX</span><h2 id="modal-title">${['confirmed','paid'].includes(payment.status)?'Pagamento confirmado':payment.kind==='deposit'?'Pague pelo seu aplicativo bancário':'Solicitação registrada'}</h2><div class="quote-box"><span>${brl(payment.amountCents/100)}</span><b>${n(payment.LC)} LC</b><small>Status: ${esc(payment.status)} · Taxa: ${brl(payment.feeCents/100)}</small></div>${payment.qrCode?`<label class="form-field"><span>Pix copia e cola</span><textarea readonly class="pix-copy-code">${esc(payment.qrCode)}</textarea></label>${btn('Copiar código Pix','copy-pix',`data-id="${esc(payment.id)}"`,'primary wide')}`:''}${payment.reason?`<div class="notice">${esc(payment.reason)}</div>`:''}${btn('Verificar pagamento','payment-status',`data-id="${esc(payment.id)}"`,'secondary wide')}`);}

function conversionModal(){modal(`<div class="modal-emblem">${I('core')}</div><h2 id="modal-title">Uma moeda. Novas possibilidades.</h2><p>Conversão pela cotação configurada no painel.</p><form id="convert-form"><label class="form-field"><span>Converter de</span><select name="from"><option value="RC">RobotCoins → LifeCoins</option><option value="LC">LifeCoins → RobotCoins</option></select></label>${input('Quantidade','amount',100,'number','min="1" step="1" required')}<div class="quote-box" id="convert-quote"></div><button class="btn primary wide" type="submit">Confirmar conversão ${I('arrow')}</button></form>`);updateQuote();}
function updateQuote(){try{const f=$('#money-form');if(f){const cents=Math.round(Number(f.amount.value)*100);if(f.dataset.kind==='deposit')$('#money-quote').innerHTML=`<span>Você recebe</span><b>${n(Math.floor(cents*state.settings.lcPerReal/100))} LC</b>`;else{const q=C.withdrawalQuote(state,cents);$('#money-quote').innerHTML=`<span>Débito total: ${n(q.debitLC)} LC</span><b>Recebe ${brl(q.receiveCents/100)}</b><small>Taxa: ${brl(q.feeCents/100)} · ${state.settings.withdrawFee}%</small>`;}}const c=$('#convert-form');if(c){const q=C.previewConversion(state,c.from.value,Number(c.amount.value));$('#convert-quote').innerHTML=`<span>${n(q.debit)} ${q.from}</span><b>→ ${n(q.credit)} ${q.to}</b><small>Arredondamento para baixo; quantidades inteiras.</small>`;}}catch(e){const target=$('#money-quote')||$('#convert-quote');if(target)target.textContent=e.message;}}
const tutorialSteps=[['Seu universo começa aqui.','LifeCoins são usadas para adquirir robôs e peças. RobotCoins vêm da produção, das missões e das batalhas.','robot'],['Dê uma chance à evolução.','Na oficina você encontra equipamentos compatíveis. Núcleos, braços e escudos podem melhorar a produção, o ataque e a defesa.','core'],['Explore no seu ritmo.','Você tem %battles% batalhas gratuitas por dia. Seu robô tem prazo e quantidade de usos próprios. O modo história traz recompensas únicas.','story'],['Sua primeira faísca.','Tutorial concluído! Resgate o bônus e explore os robôs disponíveis na oficina.','gift']];
function showTutorial(){if(state.profile.tutorial){toast('Tutorial concluído. Sua recompensa já foi recebida.');return;}const [title,body,i]=tutorialSteps[tutorialStep];modal(`<div class="tutorial-step">PASSO ${tutorialStep+1} DE 4</div><div class="modal-emblem">${I(i)}</div><h2 id="modal-title">${ui(title)}</h2><p>${body.replace('%battles%',state.settings.freeBattles)}</p><div class="tutorial-dots">${tutorialSteps.map((x,j)=>`<i class="${j<=tutorialStep?'on':''}"></i>`).join('')}</div>${btn(tutorialStep===3?'Resgatar '+state.settings.tutorialBonus+' LC':'Continuar '+I('arrow'),tutorialStep===3?'tutorial-claim':'tutorial-next','','primary wide')}`);}
function editRobot(id){const r=state.catalog.find(x=>x.id===id)||{...C.DEFAULT_ROBOTS[0],id:'new',name:'Novo robô'};modal(`<h2 id="modal-title">${id==='new'?'Novo robô':'Editar robô'}</h2><form id="robot-form" data-id="${esc(r.id)}"><label class="form-field"><span>Formato da imagem</span><select name="artKind">${[['builtin','Arte original'],['portrait','Imagem única'],['atlas6x6','Atlas: 36 poses (6 × 6)'],['atlas4x4','Atlas: 16 poses (4 × 4)']].map(([id,label])=>`<option value="${id}" ${r.artKind===id?'selected':''}>${label}</option>`).join('')}</select></label><div class="form-grid">${input('Nome','name',r.name,'text','required maxlength="40"')}<label class="form-field"><span>Classe</span><select name="type">${['explorer','striker','guardian'].map(x=>`<option ${x===r.type?'selected':''}>${x}</option>`).join('')}</select></label>${input('Título de apresentação','subtitle',r.subtitle||'','text','maxlength="120"')}${input('Espaços do robô (core, arm, shield, booster, sensor)','slots',(r.slots||['core','arm','shield']).join(', '),'text','required')}${input('Identificação do modelo','serial',r.serial||'','text','maxlength="30"')}${input('Assinatura do robô','signature',r.signature||'','text','maxlength="120"')}${input('Preço','price',r.price,'number','min="1" required')}<label class="form-field"><span>Moeda</span><select name="currency"><option ${r.currency==='LC'?'selected':''}>LC</option><option ${r.currency==='RC'?'selected':''}>RC</option></select></label>${input('Produção base diária RC (antes do multiplicador)','daily',r.daily,'number','min="1" required')}${input('Prazo em dias','lifetime',r.lifetime,'number','min="1" required')}${input('Usos totais em batalhas','maxBattles',r.maxBattles,'number','min="1" required')}${input('Ataque','attack',r.attack,'number','min="1" required')}${input('Defesa','defense',r.defense,'number','min="1" required')}${input('Vida','health',r.health,'number','min="1" required')}<label class="form-field"><span>Raridade</span><select name="rarity">${['Comum','Raro','Épico','Lendário'].map(x=>`<option ${x===r.rarity?'selected':''}>${x}</option>`).join('')}</select></label><label class="form-field"><span>Sprite</span><select name="asset">${[...new Set([...C.ROBOT_ASSETS,r.asset,...mediaItems('image').map(m=>m.ref)])].filter(Boolean).map(x=>`<option value="${esc(x)}" ${x===r.asset?'selected':''}>${esc(x)}</option>`).join('')}</select></label>${input('Cor','color',r.color,'color')}<label class="form-field"><span>Animações de combate</span><select name="animationAsset"><option value="" ${!r.animationAsset?'selected':''}>Novas poses do modelo</option><option value="legacy" ${r.animationAsset==='legacy'?'selected':''}>Atlas original</option>${COMBAT_ASSETS.map(x=>`<option value="${x}" ${r.animationAsset===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="form-field"><span>Estilo dos efeitos de combate</span><select name="combatStyle">${COMBAT_STYLES.map(([key,label])=>`<option value="${key}" ${(r.combatStyle||robotCombatProfile(r).style)===key?'selected':''}>${label}</option>`).join('')}</select></label>${input('Tom dos efeitos (0,5 a 2)','soundPitch',r.soundPitch||robotCombatProfile(r).pitch,'number','min="0.5" max="2" step="0.01" required')}</div>${textarea('Escala das poses (JSON: 0 repouso, 1 ataque, 2 dano, 3 vitória, 4 defesa, 5 especial; valores de 0,5 a 1,5)','poseScales',JSON.stringify(r.poseScales||{}))}${textarea('Descrição','description',r.description)}<button type="submit" class="btn primary wide">Salvar robô</button></form>`,'large');}
function editPart(id){const p=state.parts.find(x=>x.id===id)||{...C.DEFAULT_PARTS[0],id:'new',name:'Nova peça'};modal(`<h2 id="modal-title">${id==='new'?'Nova peça':'Editar equipamento'}</h2><form id="part-form" data-id="${esc(p.id)}"><div class="form-grid">${input('Nome','name',p.name,'text','required maxlength="40"')}${input('Título de apresentação','subtitle',p.subtitle||'','text','maxlength="120"')}<label class="form-field"><span>Raridade</span><select name="rarity">${['Comum','Raro','Épico','Lendário'].map(x=>`<option ${x===p.rarity?'selected':''}>${x}</option>`).join('')}</select></label>${input('Preço','price',p.price,'number','min="1" required')}<label class="form-field"><span>Moeda</span><select name="currency"><option ${p.currency==='LC'?'selected':''}>LC</option><option ${p.currency==='RC'?'selected':''}>RC</option></select></label><label class="form-field"><span>Espaço</span><select name="slot">${['core','arm','shield','booster','sensor'].map(x=>`<option ${x===p.slot?'selected':''}>${x}</option>`).join('')}</select></label>${input('Bônus produção %','production',p.production,'number','min="0" required')}${input('Bônus ataque','attack',p.attack,'number','min="0" required')}${input('Bônus defesa','defense',p.defense,'number','min="0" required')}${input('Nível inicial','level',p.level,'number','min="1" required')}<label class="form-field"><span>Imagem da peça</span><select name="asset">${[...new Set([...Object.values(PART_ART),p.asset,...mediaItems('image').map(m=>m.ref)])].filter(Boolean).map(asset=>`<option value="${esc(asset)}" ${asset===partAsset(p)?'selected':''}>${esc(asset)}</option>`).join('')}</select></label></div><fieldset><legend>Tipos compatíveis</legend>${['explorer','striker','guardian'].map(x=>`<label class="checkbox"><input type="checkbox" name="compatible" value="${x}" ${p.compatible.includes(x)?'checked':''}>${x}</label>`).join('')}</fieldset>${textarea('Descrição','description',p.description)}<button class="btn primary wide" type="submit">Salvar equipamento</button></form>`,'large');}
function chapterModal(id){battlePresentation.chapter(id);}

async function startBattle(id){if(!API.isDemo){toast('Use Buscar batalha na arena para encontrar seu adversário.',true);return;}const o=typeof id==='object'?id:opponents().find(x=>x.id===id);try{const ticket=C.beginBattle(state,selected()?.uid,o);save();audio.setScene('combat');audio.play('start');combat={ticket,playerHP:ticket.player.health,enemyHP:o.health,energy:0,round:1,busy:false,log:'Escolha seu movimento.',playerRow:0,enemyRow:0};renderCombat();}catch(e){toast(e.message,true);}}
function renderCombat(){if(combat)modal(battlePresentation.arena(combat),'combat-modal immersive-combat');}

function combatMove(kind){
 if(combat?.remote){remoteCombat.move(kind);return;}if(combat?.kind==='guild'){guildCombat.move(kind);return;}if(combat?.kind==='story'){chapterGame.move(kind);return;}if(!combat||combat.busy)return;
 const b=combat;if(kind==='special'&&b.energy<b.ticket.rules.energyMax)return;if(!['attack','shield','special'].includes(kind))return;
 const p=b.ticket.player,o=b.ticket.opponent,rules=b.ticket.rules,boost=kind==='special'?rules.specialMultiplier:kind==='shield'?rules.shieldAttackMultiplier:rules.attackMultiplier;
 const damage=Math.max(rules.damageMin,Math.round(p.attack*boost-o.defense*rules.defenseAbsorption)),enemyHP=Math.max(0,b.enemyHP-damage);
 const retaliation=enemyHP>0?Math.max(rules.retaliationMin,Math.round((o.attack*(rules.randomBase+Math.random()*rules.randomVariance)-p.defense*rules.playerDefenseAbsorption)*(kind==='shield'?rules.shieldReduction:1))):0;
 if(kind==='special')b.energy=0;else b.energy=Math.min(rules.energyMax,b.energy+1);
 const result={damage,enemyHP,retaliation,playerHP:Math.max(0,b.playerHP-retaliation),defeated:enemyHP<=0};
 presentCombatTurn({battle:b,kind,result,render:renderCombat,later:(battle,fn,ms)=>setTimeout(()=>{if(combat===battle)fn();},ms),audio,onDefeated:()=>finishBattle(true),onComplete:()=>{if(b.playerHP<=0){finishBattle(false);return;}b.round++;b.log='Seu próximo movimento.';renderCombat();}});
}

function finishBattle(win){const b=combat;try{C.resolveBattle(state,b.ticket,win);audio.play(win?'victory':'lose');save();combat=null;render();modal(`<div class="battle-result ${win?'win':'lose'}">${sprite(b.ticket.player,'result-sprite',win?3:2)}<span class="eyebrow">BATALHA ENCERRADA</span><h2 id="modal-title">${win?'Vitória!':'Um novo aprendizado.'}</h2><p>${win?'Sua equipe está cada vez mais forte.':'Volte à oficina e prepare sua próxima evolução.'}</p><div class="result-reward">${coin('RC')}${win?'+':'−'}${win?b.ticket.reward:b.ticket.loss} RC <small>de teste</small></div>${btn('Voltar à arena','close','','primary wide')}</div>`);}catch(e){combat=null;toast(e.message,true);closeModal();}}
function absorbRemote(data){if(!data?.profile)return;const selected=state.selectedRobot;state={...C.initialState(),depositedCents:0,withdrawnCents:0,...data,settings:{...C.DEFAULT_SETTINGS,...data.settings,name:'LifeBots'},serverAuthoritative:true};state.settings={...state.settings,rules:{...C.DEFAULT_SETTINGS.rules,...state.settings.rules},audio:{...C.DEFAULT_AUDIO,...state.settings.audio},copy:{...C.DEFAULT_COPY,...state.settings.copy}};if(/teste|prévia|fictíci/i.test(state.settings.withdrawalRules))state.settings.withdrawalRules=C.DEFAULT_SETTINGS.withdrawalRules;if(selected&&state.robots.some(r=>r.uid===selected))state.selectedRobot=selected;remoteLoaded=true;}
async function remoteAction(action,payload={}){const reply=await API.action(action,payload);if(reply.data?.snapshot)absorbRemote(reply.data.snapshot);floatingChat.refresh();return reply.data?.result??reply.data??reply;}
async function loadRemote(){const data=(await API.action('snapshot')).data;if(!data?.profile)throw new Error('Não foi possível carregar a conta.');absorbRemote(data);await loadMedia(state.profile.id,API.mediaAdapter());if(state.activeArena&&!combat&&!matchmaking)remoteCombat.start(state.activeArena);}
async function findGuildBattle(eventId,uid){if(combat||matchmaking)return;const q={id:C.uuid()};matchmaking=q;modal('<h2 id="modal-title">Buscando adversário de outra guilda…</h2>'+btn('Cancelar busca','arena-cancel','','secondary wide'));const search=async()=>{if(matchmaking!==q)return;try{const result=await remoteAction('guild_find_battle',{event_id:eventId,robot_id:uid});if(matchmaking!==q)return;if(result.match){matchmaking=null;remoteCombat.start(result.match);}else setTimeout(search,1000);}catch(e){matchmaking=null;closeModal();toast(e.message,true);}};await search();}

