document.addEventListener('change',e=>{void mediaAdmin.change(e.target);if(e.target.name==='waveCount')contentAdmin.syncWaves(e.target.closest('form'));if(e.target.id==='robot-selector'){state.selectedRobot=e.target.value;save();if(!$('#modal-root').innerHTML)render();}if(e.target.closest('#convert-form'))updateQuote();});
document.addEventListener('input',e=>{if(e.target.closest('#floating-chat-form'))floatingChat.setDraft(e.target.value);if(e.target.closest('#money-form,#convert-form'))updateQuote();});
document.addEventListener('submit',async e=>{e.preventDefault();void audio.unlock();const f=e.target,fd=new FormData(f),v=Object.fromEntries(fd);try{if(await socialAdmin.submit(f,v)||await adminOperations.submit(f,v)||await contentAdmin.submit(f,v))return;switch(f.id){
 case 'floating-chat-form':case 'chat-form':{const sent=await mutate(s=>sendMessage(s,f.dataset.room,v.message),'',{action:'chat_send',payload:{room:f.dataset.room,message:v.message}},{keepGame:f.id==='floating-chat-form'});if(sent&&f.id==='floating-chat-form')floatingChat.clearDraft(f.dataset.room);break;}
 case 'guild-create-form':await mutate(s=>Guild.createGuild(s,v.name,v.tag,v.description),'Guilda criada.',{action:'guild_create',payload:{name:v.name,tag:v.tag,description:v.description}});break;
 case 'guild-test-invite-form':if(!API.isDemo)throw new Error('Somente na demonstração.');await mutate(s=>Guild.joinGuild(s,f.dataset.id,v.inviterId,v.userId),'Entrada de exemplo registrada.');break;
 case 'trade-create-form':await mutate(s=>Trading.createListing(s,selected()?.uid,v.kind,Number(v.priceLC)),'Oferta criada.',{action:'trade_create',payload:{robot_id:selected()?.uid,kind:v.kind,price_lc:Number(v.priceLC)}});break;
 case 'trade-propose-form':await mutate(s=>Trading.proposeSwap(s,f.dataset.id,selected()?.uid),'Proposta enviada. Robô reservado até revisão.',{action:'trade_propose',payload:{listing_id:f.dataset.id,robot_id:selected()?.uid}});break;
 case 'audio-preferences-form':await audio.setPreferences({enabled:v.enabled==='on',music:v.music==='on',effects:v.effects==='on',volume:Number(v.volume)});closeModal();syncAudio();break;
 case 'money-form':if(!API.isDemo){const submit=f.querySelector('[type=submit]');submit.disabled=true;try{f.dataset.requestKey ||= C.uuid();const payment=await remoteAction(f.dataset.kind,{idempotency_key:f.dataset.requestKey,amount_cents:Math.round(Number(v.amount)*100),...(f.dataset.kind==='withdraw'?{pix_key:v.pix_key,pix_key_type:v.pix_key_type,recipient_document:v.recipient_document}:{})});render();paymentView(payment);}finally{submit.disabled=false;}break;}await mutate(s=>f.dataset.kind==='deposit'?C.deposit(s,Math.round(Number(v.amount)*100)):C.withdraw(s,Math.round(Number(v.amount)*100)),f.dataset.kind==='deposit'?'Depósito fictício adicionado.':state.settings.autoWithdrawals?'Pedido de saque registrado pela política automática.':'Pedido enviado para aprovação demonstrativa.');break;
 case 'convert-form':await mutate(s=>C.convert(s,v.from,Number(v.amount)),'Conversão concluída.',{action:'convert',payload:{from:v.from,amount:Number(v.amount)}});break;
 case 'profile-form':await mutate(s=>{s.profile.name=v.name.trim();s.profile.shareWhatsApp=v.shareWhatsapp==='on';},'Perfil atualizado.',{action:'profile',payload:{display_name:v.name.trim(),share_whatsapp:v.shareWhatsapp==='on'}});break;
 case 'equip-form':await mutate(s=>C.equip(s,$('#robot-selector').value,f.dataset.id),'Peça equipada.',{action:'equip',payload:{robot_id:$('#robot-selector').value,equipment_id:f.dataset.id}});break;
 case 'password-recovery-form':if(v.password!==v.confirm)throw new Error('As senhas precisam ser iguais.');await API.updatePassword(v.password);closeModal();location.hash='login';toast('Senha atualizada.');break;
 case 'auth-form':{const status=$('#auth-status'),submit=f.querySelector('[type="submit"]');submit.disabled=true;status.textContent='Preparando sua jornada…';try{if(API.isDemo){const draft=C.clone(state);if(v.name)draft.profile.name=v.name.trim();draft.profile.email=v.email;if(authMode==='signup'){acceptDemoReferral(draft,v.referralCode);draft.profile.whatsapp=v.whatsapp||'';}state=draft;save();location.hash='home';toast('Acesso demonstrativo. Nenhuma senha foi armazenada.');}else{const result=authMode==='signup'?await API.signUp(v.email,v.password,v.name,v.whatsapp,normalizeReferral(v.referralCode),v.shareWhatsapp==='on'):await API.signIn(v.email,v.password);if(authMode==='signup'&&!result.session){status.textContent='Confirme seu e-mail para entrar.';break;}await loadRemote();await startLiveUpdates();location.hash='home';}}finally{submit.disabled=false;}break;}
 case 'admin-economy':{const next={...state.settings};for(const k of Object.keys(v))if(!k.startsWith('commission'))next[k]=Number(v[k]);next.commissions=[0,1,2].map(i=>Number(v['commission'+i]));C.validateSettings(next);await mutate(s=>{C.collect(s);s.settings=next;},'Economia atualizada.',{action:'admin_save',payload:{settings:next}});break;}
 case 'admin-layout':{const next={...state.settings,...v,backgroundIntensity:Number(v.backgroundIntensity),visualMotion:v.visualMotion==='on',battleAtmosphere:v.battleAtmosphere==='on',authRobotIds:[0,1,2].map(i=>v['authRobot'+i]||state.settings.authRobotIds[i])};for(const i of [0,1,2])delete next['authRobot'+i];C.validateSettings(next);await mutate(s=>s.settings=next,'Visual e mensagens atualizados.',{action:'admin_save',payload:{settings:next}});break;}
 case 'robot-form':{const r={...v,id:f.dataset.id==='new'?C.uuid():f.dataset.id};r.slots=(v.slots||'core,arm,shield').split(',').map(x=>x.trim()).filter(Boolean);if(!r.slots.length||new Set(r.slots).size!==r.slots.length||r.slots.some(x=>!['core','arm','shield','booster','sensor'].includes(x)))throw new Error('Espaços de robô inválidos.');r.poseScales=JSON.parse(v.poseScales||'{}');if(!r.poseScales||typeof r.poseScales!=='object'||Array.isArray(r.poseScales)||Object.entries(r.poseScales).some(([key,value])=>!/[0-5]/.test(key)||key.length!==1||!Number.isFinite(value)||value<.5||value>1.5))throw new Error('Escala das poses inválida.');r.soundPitch=Number(v.soundPitch??robotCombatProfile(r).pitch);if(!Number.isFinite(r.soundPitch)||r.soundPitch<.5||r.soundPitch>2||!COMBAT_STYLES.some(([id])=>id===(r.combatStyle||robotCombatProfile(r).style))||r.animationAsset&&!['legacy',...COMBAT_ASSETS].includes(r.animationAsset))throw new Error('Animações ou efeitos do robô inválidos.');for(const k of ['price','daily','lifetime','maxBattles','attack','defense','health']){r[k]=Number(v[k]);if(!Number.isSafeInteger(r[k])||r[k]<1)throw new Error('Valores do robô devem ser inteiros positivos.');}await mutate(s=>{C.collect(s);const idx=s.catalog.findIndex(x=>x.id===r.id);if(idx>=0)s.catalog[idx]=r;else s.catalog.push(r);},'Catálogo atualizado.',{action:'admin_save',payload:{robot:r}});break;}
 case 'part-form':{const p={...v,id:f.dataset.id==='new'?C.uuid():f.dataset.id,compatible:fd.getAll('compatible')};if(!p.compatible.length)throw new Error('Escolha pelo menos um tipo compatível.');for(const k of ['price','production','attack','defense','level']){p[k]=Number(v[k]);if(!Number.isSafeInteger(p[k])||p[k]<(k==='price'||k==='level'?1:0))throw new Error('Valores do equipamento inválidos.');}await mutate(s=>{C.collect(s);const idx=s.parts.findIndex(x=>x.id===p.id);if(idx>=0)s.parts[idx]=p;else s.parts.push(p);},'Equipamento atualizado.',{action:'admin_save',payload:{part:p}});break;}
}}catch(err){toast(err.message,true);if($('#auth-status'))$('#auth-status').textContent=err.message;}});
document.addEventListener('keydown',e=>{if(!$('#modal-root').innerHTML)return;if(e.key==='Escape'){closeModal();return;}if(e.key==='Tab'){const els=$$('#modal-root button:not([disabled]), #modal-root input, #modal-root select, #modal-root textarea, #modal-root a[href]'),first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
$('#modal-root').addEventListener('click',e=>{if(e.target.classList.contains('modal-overlay'))closeModal();});
window.addEventListener('hashchange',()=>{if(combat)return;if(matchmaking)arenaQueue.cancel();page=location.hash.slice(1).split('?')[0]||'home';if(page==='chat'){page='home';const url=new URL(location.href);url.hash='home';if(window.history?.replaceState)window.history.replaceState(null,'',url.href);else location.hash='home';floatingChat.open();}if(page==='signup'){page='login';authMode='signup';}try{signupReferral=referralFromUrl(location.href)||signupReferral;}catch{}closeModal();render();window.scrollTo({top:0,behavior:'instant'});});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;});
function tick(){if(API.isDemo){const expiredOffers=Trading.expireListings(state);if(expiredOffers){save();if(!combat&&!matchmaking&&page==='market')render();}const expired=C.settleExpirations(state);if(expired.count){save();if(!combat&&!matchmaking){render();toast(`${expired.LC} LC devolvidas à carteira por expiração.`);return;}}}const ready=stats().reduce((sum,r)=>sum+r.available,0);$$('[data-live-collect]').forEach(x=>x.textContent=n(ready)+' RC');document.body.classList.toggle('world-motion-off',!state.settings.visualMotion);document.body.classList.toggle('battle-atmosphere-off',!state.settings.battleAtmosphere);document.documentElement.style.setProperty('--world-art',`url('${assetUrl(state.settings.worldBackgroundArt||sceneAsset(state.settings.worldBackground))}')`);document.documentElement.style.setProperty('--world-opacity',state.settings.backgroundIntensity??.55);document.documentElement.style.setProperty('--arena-art',`url('${assetUrl(sceneAsset('arena'))}')`);document.body.classList.toggle('compact-layout',state.settings.layout==='compact');document.documentElement.style.setProperty('--hangar-art',`url('${assetUrl(state.settings.hangarBackgroundArt||sceneAsset(state.settings.hangarBackground))}')`);}
setInterval(tick,10000);
if(page==='chat'){page='home';floatingChat.open();}
render();
installDragScroll();
document.addEventListener('visibilitychange',()=>{if(document.hidden)audio.suspend();else{tick();void audio.unlock();}});
if(!API.isDemo){API.session().then(async session=>{if(session){await loadRemote();render();await startLiveUpdates();}else{try{const appearance=await API.publicAppearance();state.settings={...state.settings,...appearance.settings,name:'LifeBots',copy:{...state.settings.copy,...appearance.settings.copy},audio:{...state.settings.audio,...appearance.settings.audio}};for(const r of appearance.catalog){const old=state.catalog.find(m=>m.id===r.id);if(old)Object.assign(old,r);else state.catalog.push(r);}primePublicMedia(appearance.media);}catch{}location.hash='login';render();}}).catch(e=>{toast(e.message,true);location.hash='login';});}
if('serviceWorker'in navigator&&['http:','https:'].includes(location.protocol)){
 const alreadyControlled=!!navigator.serviceWorker.controller;let refreshed=false;
 navigator.serviceWorker.addEventListener('controllerchange',()=>{if(alreadyControlled&&!refreshed&&!combat){refreshed=true;location.reload();}});
 navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(reg=>reg.update()).catch(()=>{});
}

async function copyInvitation(value){if(navigator.clipboard?.writeText){await navigator.clipboard.writeText(value);toast('Convite copiado.');}else modal(`<h2 id="modal-title">Seu convite</h2><p>Selecione e copie o código ou link abaixo.</p><input class="manual-copy" readonly value="${esc(value)}">`);}
function scrollMapFocus(){requestAnimationFrame(()=>{const node=$('.journey-node.focused');node?.scrollIntoView?.({behavior:'smooth',block:'nearest',inline:'center'});});}

let liveUnsubscribe,liveRefreshTimer;
async function startLiveUpdates(){if(API.isDemo||liveUnsubscribe)return;liveUnsubscribe=await API.subscribeUpdates(()=>{clearTimeout(liveRefreshTimer);liveRefreshTimer=setTimeout(async()=>{try{absorbRemote((await API.action('snapshot')).data);floatingChat.refresh();if(!combat&&!matchmaking&&!$('#modal-root').innerHTML)render();}catch{}},400);});}
if(API.isDemo)void loadMedia('demo').then(()=>{render();audio.refresh();}).catch(e=>toast(e.message,true));
if(!API.isDemo)void API.onRecovery(()=>modal(`<div class="modal-emblem">${I('shield')}</div><h2 id="modal-title">Uma nova senha para seu piloto.</h2><form id="password-recovery-form">${input('Nova senha','password','','password','minlength="10" required autocomplete="new-password"')}${input('Confirmar senha','confirm','','password','minlength="10" required autocomplete="new-password"')}<button type="submit" class="btn primary wide">Salvar nova senha</button></form>`));
